import React,{useCallback,useEffect,useMemo,useState} from "react";
import {createRoot} from "react-dom/client";
import QRCode from "qrcode";
import {eventSchedule} from "./schedule";
import {cancellationSplit,validatePolicy,type CreateEventInput,type DisputeView,type EventView,type Policy,type RegistrationView,type TxIntent,type TxReceipt,type WaitlistView} from "@seatback/contracts";
import {createApi,DEMO_MODE,isOfferExpired,lamportsToSol,requiresSession,solToLamports,type SeatBackApi} from "./api";
import "./styles.css";

type WalletProvider={publicKey?:{toBase58():string};connect():Promise<{publicKey:{toBase58():string}}>;disconnect():Promise<void>;on?(event:"accountChanged"|"disconnect",callback:(key?:{toBase58():string}|null)=>void):void;removeListener?(event:"accountChanged"|"disconnect",callback:(key?:{toBase58():string}|null)=>void):void;signMessage?(message:Uint8Array,encoding?:"utf8"):Promise<{signature:Uint8Array}>;signTransaction?(transaction:import("@solana/web3.js").Transaction):Promise<import("@solana/web3.js").Transaction>};
declare global {interface Window {solana?:WalletProvider & {isPhantom?:boolean}}}
const api:SeatBackApi=createApi();
const date=(s:number,zone?:string)=>new Intl.DateTimeFormat(undefined,{dateStyle:"medium",timeStyle:"short",...(zone?{timeZone:zone}:{})}).format(new Date(s*1000));
const short=(s:string)=>s.length>14?`${s.slice(0,5)}…${s.slice(-5)}`:s;
const errorText=(e:unknown)=>typeof e==="object"&&e!==null&&"code" in e&&(e as {code?:number}).code===4001?"The request was rejected in Phantom. Your reservation remains unchanged.":e instanceof Error?e.message:"Something went wrong. Try again.";
function usePath(){const [path,setPath]=useState(location.pathname+location.search);useEffect(()=>{const f=()=>setPath(location.pathname+location.search);window.addEventListener("popstate",f);return()=>window.removeEventListener("popstate",f)},[]);return [path,(to:string)=>{history.pushState({},"",to);setPath(to);window.scrollTo(0,0)}] as const}
function Link({to,go,children,className,...props}:{to:string;go:(s:string)=>void;children:React.ReactNode;className?:string;[k:string]:unknown}){return <a href={to} className={className} onClick={e=>{e.preventDefault();go(to)}} {...props}>{children}</a>}
function App(){const [path,go]=usePath();const [wallet,setWallet]=useState<string|null>(null);const [walletBusy,setWalletBusy]=useState(false);const [notice,setNotice]=useState("");const [csrf,setCsrf]=useState("");const pathname=path.split("?")[0]??"/";useEffect(()=>{const f=(e:Event)=>setNotice((e as CustomEvent<string>).detail);const clear=()=>{sessionStorage.removeItem("seatback.csrf");setCsrf("");setWallet(null)};const expired=()=>{clear();setNotice("Your wallet session expired. Sign in again to continue.")};const changed=(key?:{toBase58():string}|null)=>{clear();if(key){setWallet(key.toBase58());setNotice("Phantom account changed. Sign in again with the selected wallet.")}else setNotice("Phantom disconnected.")};window.solana?.on?.("accountChanged",changed);window.solana?.on?.("disconnect",changed);window.addEventListener("seatback-message",f);window.addEventListener("seatback-session-expired",expired);return()=>{window.solana?.removeListener?.("accountChanged",changed);window.solana?.removeListener?.("disconnect",changed);window.removeEventListener("seatback-message",f);window.removeEventListener("seatback-session-expired",expired)}},[]);useEffect(()=>{if(!DEMO_MODE)api.request<{wallet:string;expiresAt:number;csrfToken:string}>("/v1/auth/session").then(s=>{setWallet(s.wallet);setCsrf(s.csrfToken);sessionStorage.setItem("seatback.csrf",s.csrfToken)}).catch(()=>undefined)},[]);
 const connect=async()=>{if(!window.solana?.isPhantom){setNotice("Phantom wallet not found. Install Phantom to connect a wallet.");return}setWalletBusy(true);try{const r=await window.solana.connect();setWallet(r.publicKey.toBase58());setNotice("Wallet connected. Sign-in is a separate step.")}catch(e){setNotice(errorText(e))}finally{setWalletBusy(false)}};
 const login=async()=>{if(!wallet||!window.solana?.signMessage){setNotice("Connect a Phantom wallet that supports message signing first.");return}try{const challenge=await api.request<{challengeId:string;message:string;expiresAt:number}>("/v1/auth/challenge",{method:"POST",body:JSON.stringify({wallet,domain:location.host,uri:location.origin})});if(challenge.expiresAt<=Math.floor(Date.now()/1000))throw new Error("The sign-in challenge expired. Try again.");const signed=await window.solana.signMessage(new TextEncoder().encode(challenge.message),"utf8");if(window.solana.publicKey&&window.solana.publicKey.toBase58()!==wallet)throw new Error("Phantom switched accounts. Connect the intended wallet and try again.");const signatureBase64=btoa(String.fromCharCode(...signed.signature));const session=await api.request<{wallet:string;expiresAt:number;csrfToken:string}>("/v1/auth/verify",{method:"POST",body:JSON.stringify({challengeId:challenge.challengeId,wallet,signatureBase64})});if(session.wallet!==wallet)throw new Error("The authenticated account does not match the connected wallet.");sessionStorage.setItem("seatback.csrf",session.csrfToken);setCsrf(session.csrfToken);setNotice(`Signed in as ${short(session.wallet)}.`)}catch(e){setNotice(errorText(e))}};
 const logout=async()=>{try{await api.request("/v1/auth/logout",{method:"POST",body:"{}"})}catch{/* local session state is still cleared if the API is unavailable */}try{await window.solana?.disconnect()}catch{/* wallet extension may already be disconnected */}sessionStorage.removeItem("seatback.csrf");setCsrf("");setWallet(null);setNotice("Wallet disconnected.")};
 const shell=(content:React.ReactNode)=><><header className="topbar"><Link to="/events" go={go} className="brand"><span className="brand-mark">s</span><span>seatback<span className="brand-dot">.</span></span></Link><nav aria-label="Main navigation"><Link to="/events" go={go}>Explore</Link><Link to="/me" go={go}>My seats</Link><Link to="/organizer/events" go={go}>Organize</Link></nav><div className="top-actions">{wallet?<button className="wallet-pill" onClick={logout}><span className="online-dot"/>{short(wallet)}</button>:<button className="button button-dark connect" onClick={connect} disabled={walletBusy}>{walletBusy?"Connecting…":<><span className="phantom-mark">◈</span> Connect wallet</>}</button>}</div></header>{DEMO_MODE&&<div className="demo-banner"><span className="demo-dot"/><b>Demo data</b><span>— no transactions</span><span className="demo-note">Example content only · Devnet prototype</span></div>}{notice&&<div className="notice" role="status"><span>{notice}</span><button aria-label="Dismiss notice" onClick={()=>setNotice("")}>×</button></div>}<main className="page">{content}</main><footer className="footer"><div className="footer-brand"><span className="brand-mark small">s</span> seatback</div><span>Built for showing up. <b>Devnet only</b></span><a href="https://github.com/0xalpar/seatback" target="_blank" rel="noreferrer">Open source ↗</a></footer>{wallet&&!csrf&&<div className="signin-nudge"><span>Wallet connected · Sign in to unlock your seats</span><button className="button button-dark" onClick={login}>Sign message</button></div>}</>;
 let content:React.ReactNode;
 if(pathname==="/"||pathname==="/events")content=<Explore go={go}/>;
 else if(pathname.startsWith("/events/")){const id=pathname.split("/")[2]??"";content=<EventDetails id={id} go={go} wallet={wallet}/>}
 else if(pathname==="/organizer/events/new")content=<CreateEvent go={go} wallet={wallet}/>;
 else if(pathname==="/organizer/events")content=<OrganizerHome go={go}/>;
 else if(pathname.startsWith("/organizer/events/"))content=<OrganizerAccess id={pathname.split("/")[3]??""} go={go}/>;
 else if(pathname==="/me")content=<ParticipantHome go={go}/>;
 else if(pathname.startsWith("/offers/"))content=<Offer id={pathname.split("/")[2]??""} go={go}/>;
 else if(pathname.startsWith("/scan/"))content=<ScannerAccess id={pathname.split("/")[2]??""} go={go}/>;
 else if(pathname.startsWith("/registrations/"))content=<RegistrationDetail id={pathname.split("/")[2]??""} go={go}/>;
 else if(pathname==="/arbiter/disputes")content=<ArbiterAccess go={go}/>;
 else content=<NotFound go={go}/>;
 if(!DEMO_MODE&&requiresSession(pathname)&&!csrf)content=<AuthRequired connect={connect} login={login} wallet={wallet}/>;
 return shell(content)}

function Eyebrow({children}:{children:React.ReactNode}){return <div className="eyebrow">{children}</div>}
function PageIntro({eyebrow,title,description,action}:{eyebrow:string;title:React.ReactNode;description:string;action?:React.ReactNode}){return <div className="page-intro"><div><Eyebrow>{eyebrow}</Eyebrow><h1>{title}</h1><p>{description}</p></div>{action&&<div className="intro-action">{action}</div>}</div>}
function EventCard({event,go}:{event:EventView;go:(s:string)=>void}){const full=event.occupiedSeats+event.heldOffers>=event.capacity||event.registrationsCreated>=event.registrationLimit;const art=Math.abs([...event.id].reduce((n,c)=>n+c.charCodeAt(0),0))%3;return <article className="event-card"><Link to={`/events/${event.id}`} go={go} className="event-cover"><span className="cover-label">{event.location.split(",")[0]}</span><span className={`cover-art art-${art}`} aria-hidden="true"><i/><i/><i/><b>✳</b></span><span className="cover-date"><b>{new Date(event.policy.eventStartsAt*1000).toLocaleDateString(undefined,{day:"2-digit"})}</b><small>{new Date(event.policy.eventStartsAt*1000).toLocaleDateString(undefined,{month:"short"})}</small></span></Link><div className="event-card-body"><div className="card-meta"><span>{event.location}</span><span className={full?"status-full":"status-open"}><i/> {full?"Waitlist open":"Seats available"}</span></div><Link to={`/events/${event.id}`} go={go} className="event-title"><h2>{event.title}</h2></Link><p>{event.description}</p><div className="card-bottom"><span className="deposit"><strong>{lamportsToSol(event.policy.depositLamports)}</strong><small>refundable deposit</small></span><span className="seat-count">{Math.max(event.capacity-event.occupiedSeats-event.heldOffers,0)} / {event.capacity} seats</span></div></div></article>}
async function loadMoreEvents(q:string,cursor:string,setEvents:React.Dispatch<React.SetStateAction<EventView[]>>,setCursor:React.Dispatch<React.SetStateAction<string|null>>,setLoading:React.Dispatch<React.SetStateAction<boolean>>,setErr:React.Dispatch<React.SetStateAction<string>>){setLoading(true);try{const next=await api.events(q,cursor);setEvents(current=>[...current,...next.items]);setCursor(next.nextCursor);setErr("")}catch(e){setErr(errorText(e))}finally{setLoading(false)}}
function Explore({go}:{go:(s:string)=>void}){const [q,setQ]=useState(new URLSearchParams(location.search).get("q")??"");const [events,setEvents]=useState<EventView[]>([]);const [loading,setLoading]=useState(true);const [err,setErr]=useState("");const [cursor,setCursor]=useState<string|null>(null);useEffect(()=>{let active=true;setLoading(true);api.events(q).then(r=>{if(active){setEvents(r.items);setCursor(r.nextCursor);setErr("")}}).catch(e=>active&&setErr(errorText(e))).finally(()=>active&&setLoading(false));return()=>{active=false}},[q]);const search=(e:React.FormEvent)=>{e.preventDefault();go(`/events${q?`?q=${encodeURIComponent(q)}`:""}`)};return <><section className="hero"><div className="hero-copy"><div className="hero-kicker"><span/> The better kind of commitment</div><h1>Plans worth<br/><em>showing up for.</em></h1><p>Find your people, save your seat, and make it count. Your deposit comes back when you do.</p><form className="searchbar" onSubmit={search}><span aria-hidden="true">⌕</span><input aria-label="Search events" value={q} onChange={e=>setQ(e.target.value)} placeholder="Try ‘design’, ‘Istanbul’…"/><button className="button button-dark">Find an event <span>↗</span></button></form><div className="hero-proof"><span className="proof-avatars"><b>Y</b><b>A</b><b>S</b></span><span>Good people. Good plans. <strong>No ghosting.</strong></span></div></div><div className="hero-art" aria-label="Colorful abstract illustration of a seat"><div className="sun"/><div className="arc arc-one"/><div className="arc arc-two"/><div className="seat-shape"><div/><span/></div><div className="spark spark-one">✳</div><div className="spark spark-two">✦</div><div className="hero-tag">YOUR SEAT<br/><b>IS WAITING</b></div></div><div className="hero-index"><span>01</span><i/> A new way to meet up</div></section><div className="section-heading"><div><Eyebrow>THE GOOD STUFF</Eyebrow><h2>Find your next <em>thing.</em></h2></div><span className="section-count">{loading?"…":`${events.length.toString().padStart(2,"0")} events`} <span>↘</span></span></div>{err?<ErrorPanel message={err} retry={()=>setQ(x=>x+" ")} />:loading?<div className="loading-grid" aria-label="Loading events"><div/><div/><div/></div>:events.length?<div className="event-grid">{events.map(e=><EventCard key={e.id} event={e} go={go}/>)}</div>:<Empty icon="⌕" title="Nothing on the calendar just yet" detail="Try a different search, or check back soon for new gatherings." action={<button className="text-button" onClick={()=>setQ("")}>Clear search ↗</button>}/>}<section className="manifesto"><div className="manifesto-glyph">✳</div><div><Eyebrow>A LITTLE MORE INTENTION</Eyebrow><h2>Save a seat.<br/><em>Make a memory.</em></h2></div><p>Every SeatBack event has a refundable deposit. Show up and it comes right back. Life happens? Clear rules mean no awkward surprises.</p><Link to="/organizer/events/new" go={go} className="text-button">Bring people together ↗</Link></section>{cursor&&<button className="button button-outline centered" disabled={loading} onClick={()=>void loadMoreEvents(q,cursor,setEvents,setCursor,setLoading,setErr)}>{loading?"Loading…":"Load more events"}</button>}</>}

function ErrorPanel({message,retry}:{message:string;retry?:()=>void}){return <div className="error-panel" role="alert"><span className="error-icon">!</span><div><b>We couldn’t load this</b><p>{message}</p>{retry&&<button className="text-button" onClick={retry}>Try again ↗</button>}</div></div>}
function Empty({icon,title,detail,action}:{icon:string;title:string;detail:string;action?:React.ReactNode}){return <div className="empty"><span>{icon}</span><h3>{title}</h3><p>{detail}</p>{action}</div>}
function DetailLoader<T>({load,render,errorRender}:{load:()=>Promise<T>;render:(v:T)=>React.ReactNode;errorRender?:(message:string)=>React.ReactNode}){const [value,setValue]=useState<T|null>(null);const [err,setErr]=useState("");useEffect(()=>{let ok=true;const refresh=()=>{load().then(v=>{if(ok){setValue(v);setErr("")}}).catch(e=>ok&&setErr(errorText(e)))};refresh();window.addEventListener("seatback-refresh",refresh);return()=>{ok=false;window.removeEventListener("seatback-refresh",refresh)}},[load]);if(err)return <>{errorRender?errorRender(err):<ErrorPanel message={err}/>}</>;if(value===null)return <div className="loading-line">Gathering the details<span>…</span></div>;return <>{render(value)}</>}
function EventDetails({id,go,wallet}:{id:string;go:(s:string)=>void;wallet:string|null}){const [code,setCode]=useState("");const [message,setMessage]=useState("");const [busy,setBusy]=useState(false);const load=useCallback(()=>api.event(id),[id]);return <DetailLoader load={load} errorRender={error=><><ErrorPanel message={error}/><section className="policy-card"><h2>Have a private invitation?</h2><p>Sign in with your wallet and enter the invitation code. Unknown and private events share the same access response.</p><form onSubmit={async e=>{e.preventDefault();try{await api.request(`/v1/events/${id}/access`,{method:"POST",body:JSON.stringify({code})});window.dispatchEvent(new Event("seatback-refresh"))}catch(e){setMessage(errorText(e))}}}><label htmlFor="invitation-code">Invitation code</label><input id="invitation-code" required value={code} onChange={e=>setCode(e.target.value)}/><button className="button button-dark" disabled={!wallet}>Unlock event</button></form>{message&&<p role="status">{message}</p>}</section></>} render={event=><><div className="crumb"><button onClick={()=>go("/events")}>← All events</button><span>/</span><span>{event.location}</span></div><div className="detail-layout"><div><div className="detail-art"><span className="detail-art-word">MAKE IT<br/><em>HAPPEN.</em></span><div className="detail-art-circles"><i/><i/><i/></div><span className="detail-date-stamp">{date(event.policy.eventStartsAt).split(",")[0]}</span></div><Eyebrow>THE GATHERING</Eyebrow><h1 className="detail-title">{event.title}</h1><p className="detail-description">{event.description}</p><div className="detail-facts"><div><span>⌖</span><div><small>WHERE</small><b>{event.location}</b></div></div><div><span>◷</span><div><small>WHEN</small><b>{date(event.policy.eventStartsAt)}</b><small className="utc-line">{date(event.policy.eventStartsAt,"UTC")} · UTC</small></div></div></div><section className="policy-card"><div className="policy-head"><div><Eyebrow>YOUR DEPOSIT, YOUR CALL</Eyebrow><h2>Clear rules. <em>No surprises.</em></h2></div><span className="policy-amount">{lamportsToSol(event.policy.depositLamports)}</span></div><PolicyTimeline policy={event.policy}/><p className="fine-print">Deposit is held in a Devnet program vault. Rent and transaction fees are separate. Refunds depend on attendance and the deadlines above.</p></section></div><aside className="booking-card"><div className="booking-top"><span className="pill pill-open">● {event.status}</span><span>{event.visibility==="private"?"Private gathering":"Open to everyone"}</span></div><h2>Your seat<br/>is waiting.</h2><p>One refundable deposit holds your place. You’ll get it back when you check in.</p><div className="seat-bar"><div><span>Seats</span><b>{event.occupiedSeats+event.heldOffers} <small>/ {event.capacity}</small></b></div><div className="progress"><i style={{width:`${Math.min(100,(event.occupiedSeats+event.heldOffers)/event.capacity*100)}%`}}/></div></div>{event.occupiedSeats+event.heldOffers>=event.capacity?<button className="button button-dark button-wide" disabled={busy||!wallet} onClick={()=>doAction(api.action(`/v1/events/${event.id}/waitlist`),setBusy,setMessage)}>Join free waitlist <span>↗</span></button>:<button className="button button-dark button-wide" disabled={!wallet||busy} title={!wallet?"Connect and sign in to continue":""} onClick={()=>doAction(api.action(`/v1/events/${event.id}/register`),setBusy,setMessage)}>{busy?"Preparing wallet transaction…":"Reserve with Phantom"}<span>↗</span></button>}<div className="booking-lock">⌑ <span>Wallet signature required · Devnet only</span></div>{!wallet&&<p className="booking-tip">Connect your wallet to save a seat.</p>}{event.visibility==="private"&&<form className="private-code" onSubmit={async e=>{e.preventDefault();try{await api.request(`/v1/events/${event.id}/access`,{method:"POST",body:JSON.stringify({code})});setMessage("Admission granted for this session.")}catch(e){setMessage(errorText(e))}}}><label htmlFor="access-code">Have an access code?</label><div><input id="access-code" value={code} onChange={e=>setCode(e.target.value)} placeholder="Enter private code"/><button aria-label="Submit access code">→</button></div></form>}{message&&<p className="inline-message" role="status">{message}</p>}</aside></div></>}/>}
function PolicyTimeline({policy:p}:{policy:Policy}){return <div className="timeline"><div className="timeline-line"/><div className="timeline-item"><span className="timeline-dot mint"/><small>BEFORE {date(p.rule1Deadline).split(",")[0]}</small><b>100% back</b><span>Cancel early, get it all back.</span></div><div className="timeline-item"><span className="timeline-dot yellow"/><small>UNTIL {date(p.rule2Deadline).split(",")[0]}</small><b>30% back</b><span>A little later, a little less.</span></div><div className="timeline-item"><span className="timeline-dot coral"/><small>AFTER THAT</small><b>Check in to get 100%</b><span>Show up and your deposit returns.</span></div></div>}
async function doAction(p:Promise<unknown>,busy:(b:boolean)=>void,set:(s:string)=>void){busy(true);try{const result=await p;if(DEMO_MODE){set("Demo only — no transaction was sent.");return}if(typeof result==="object"&&result!==null&&"status" in result&&! ("transactionBase64" in result)){const w=result as WaitlistView;window.dispatchEvent(new Event("seatback-refresh"));set(w.status==="offered"?`Waitlist offer received; expires ${w.offerExpiresAt?date(w.offerExpiresAt):"soon"}.`:`Joined the waitlist (position ${w.position}).`);return}const wrapped=result as {intent?:TxIntent};const intent=(wrapped.intent??result) as TxIntent;if(!intent?.transactionBase64)throw new Error("The API did not return a transaction intent.");if(!window.solana?.signTransaction||!window.solana.publicKey)throw new Error("Connect Phantom before signing.");set("Review the Devnet transaction in Phantom…");const submitted=await (await import("./transactions")).signAndSubmit(intent,{walletAddress:window.solana.publicKey.toBase58(),signTransaction:window.solana.signTransaction.bind(window.solana)});if(submitted.status==="pending"&&!submitted.signature){set("Pending participant co-signature. This is not a completed transaction.");return}const final=await (await import("./transactions")).waitForReceipt(intent,submitted,p=>api.request<TxReceipt>(p),()=>set("Transaction submitted; waiting for finalized confirmation…"));if(final.status==="confirmed")window.dispatchEvent(new Event("seatback-refresh"));set(final.status==="confirmed"?`Confirmed on Devnet${final.signature?` · ${short(final.signature)}`:""}.`:`Transaction ${final.status}.`)}catch(e){set(errorText(e))}finally{busy(false)}}
function OrganizerHome({go}:{go:(s:string)=>void}){return <DetailLoader load={()=>api.organizerEvents()} render={page=><><PageIntro eyebrow="YOUR CORNER OF SEATBACK" title={<>Gather your<br/><em>people.</em></>} description="Everything you need to bring a good thing together." action={<button className="button button-dark" onClick={()=>go("/organizer/events/new")}>＋ Create an event</button>}/><div className="dashboard-stats"><Stat label="UPCOMING EVENTS" value={String(page.items.length).padStart(2,"0")} icon="✳"/><Stat label="SEATS FILLED" value={String(page.items.reduce((a,e)=>a+e.occupiedSeats,0))} icon="◉"/><Stat label="WAITING LISTS" value="01" icon="↗"/></div><div className="section-heading dash-heading"><div><Eyebrow>IN YOUR HANDS</Eyebrow><h2>Your events</h2></div><span className="section-count">{page.items.length} total</span></div>{page.items.length?<div className="organizer-list">{page.items.map(e=><Link to={`/organizer/events/${e.id}`} go={go} className="organizer-row" key={e.id}><div className="row-color"><span>✳</span></div><div className="row-main"><b>{e.title}</b><span>{e.location} <i>·</i> {date(e.policy.eventStartsAt)}</span></div><div className="row-seats"><b>{e.occupiedSeats}<small> / {e.capacity}</small></b><span>seats filled</span></div><span className="row-status"><i/> {e.status}</span><span className="row-arrow">↗</span></Link>)}</div>:<Empty icon="✳" title="Your first gathering starts here" detail="Create an event, set the rules, and invite your people." action={<button className="button button-dark" onClick={()=>go("/organizer/events/new")}>Create an event ↗</button>}/>}</>}/>}
function Stat({label,value,icon}:{label:string;value:string;icon:string}){return <div className="stat-card"><span className="stat-icon">{icon}</span><span className="stat-label">{label}</span><b>{value}</b><span className="stat-note">across your account</span></div>}
function CreateEvent({go,wallet}:{go:(s:string)=>void;wallet:string|null}){const [title,setTitle]=useState("");const [description,setDescription]=useState("");const [location,setLocation]=useState("");const [capacity,setCapacity]=useState("30");const [limit,setLimit]=useState("45");const [amount,setAmount]=useState("0.25");const [starts,setStarts]=useState("");const [opens,setOpens]=useState("");const [closes,setCloses]=useState("");const [ends,setEnds]=useState("");const [rule1,setRule1]=useState("");const [rule2,setRule2]=useState("");const [privateEvent,setPrivateEvent]=useState(false);const [code,setCode]=useState("");const [agree,setAgree]=useState(false);const [msg,setMsg]=useState("");const [busy,setBusy]=useState(false);
 const submit=async(e:React.FormEvent)=>{e.preventDefault();setMsg("");if(!wallet){setMsg("Connect a Phantom wallet before creating an event.");return}try{const start=Math.floor(new Date(starts).getTime()/1000);const r1=Math.floor(new Date(rule1).getTime()/1000);const r2=Math.floor(new Date(rule2).getTime()/1000);const policy:Policy={depositLamports:solToLamports(amount),rule1Deadline:r1,rule2Deadline:r2,checkInOpensAt:Math.floor(new Date(opens).getTime()/1000),eventStartsAt:start,eventEndsAt:Math.floor(new Date(ends).getTime()/1000),checkInClosesAt:Math.floor(new Date(closes).getTime()/1000),disputeSeconds:86400};validatePolicy(policy);if(Number(limit)<Number(capacity))throw new Error("Lifetime registration limit must be at least the seat capacity.");if(privateEvent&&code.length<8)throw new Error("Private access codes must contain at least 8 characters.");if(!agree)throw new Error("Please acknowledge that event terms lock at the first registration.");const input:CreateEventInput={title,description,location,visibility:privateEvent?"private":"public",...(privateEvent?{accessCode:code}:{}),capacity:Number(capacity),registrationLimit:Number(limit),policy};setBusy(true);const result=await api.request<{eventId:string;intent:TxIntent}>("/v1/events",{method:"POST",body:JSON.stringify(input)});if(DEMO_MODE){setMsg("Demo only — no event or transaction was created.");return}if(!window.solana?.signTransaction||!window.solana.publicKey)throw new Error("Connect Phantom before signing.");setMsg("Review the event creation transaction in Phantom…");const signed=await (await import("./transactions")).signAndSubmit(result.intent,{walletAddress:window.solana.publicKey.toBase58(),signTransaction:window.solana.signTransaction.bind(window.solana)});const final=await (await import("./transactions")).waitForReceipt(result.intent,signed,p=>api.request<TxReceipt>(p),()=>setMsg("Event transaction pending final confirmation; it is not published yet."));if(final.status!=="confirmed"){setMsg("Event creation failed and is not published.");return}setMsg("Event confirmed on Devnet.");go(`/organizer/events/${result.eventId}`)}catch(e){setMsg(errorText(e))}finally{setBusy(false)}};
 return <><div className="crumb"><button onClick={()=>go("/organizer/events")}>← Organizer home</button></div><PageIntro eyebrow="MAKE A LITTLE MAGIC" title={<>Bring people<br/><em>together.</em></>} description="Start with the basics. Your event rules become the promise your guests can count on."/><form className="create-layout" onSubmit={submit}><div className="form-column"><section className="form-card"><div className="form-section-head"><span>01</span><div><h2>The gathering</h2><p>What should people know?</p></div></div><Field label="Event name" hint="Give it a name people will remember."><input required maxLength={120} value={title} onChange={e=>setTitle(e.target.value)} placeholder="e.g. Sunday ceramics club"/></Field><Field label="A little about it"><textarea maxLength={10000} rows={4} value={description} onChange={e=>setDescription(e.target.value)} placeholder="What will happen? Who is it for? Make it yours."/></Field><Field label="Where are we meeting?"><input required maxLength={500} value={location} onChange={e=>setLocation(e.target.value)} placeholder="Venue, neighborhood, or address"/></Field><Field label="Starts at" hint="Shown in your local time and UTC in listings."><input required type="datetime-local" value={starts} onChange={e=>{setStarts(e.target.value);const schedule=eventSchedule(e.target.value);setRule1(schedule.rule1);setRule2(schedule.rule2);setOpens(schedule.opens);setCloses(schedule.closes);setEnds(schedule.ends)}}/></Field><Field label="Check-in opens"><input required type="datetime-local" value={opens} onChange={e=>setOpens(e.target.value)}/></Field><Field label="Check-in closes"><input required type="datetime-local" value={closes} onChange={e=>setCloses(e.target.value)}/></Field><Field label="Event ends"><input required type="datetime-local" value={ends} onChange={e=>setEnds(e.target.value)}/></Field></section><section className="form-card"><div className="form-section-head"><span>02</span><div><h2>Make the rules clear</h2><p>A refundable deposit helps everyone show up.</p></div></div><div className="form-row"><Field label="Seat capacity"><input type="number" min="1" max="10000" required value={capacity} onChange={e=>setCapacity(e.target.value)}/></Field><Field label="Lifetime registration limit" hint="Includes past cancellations."><input type="number" min="1" max="100000" required value={limit} onChange={e=>setLimit(e.target.value)}/></Field></div><Field label="Refundable deposit" hint="SOL on Devnet. Fees and rent are separate."><div className="input-suffix"><input inputMode="decimal" required value={amount} onChange={e=>setAmount(e.target.value)}/><span>◎ SOL</span></div></Field><div className="form-row"><Field label="100% refund until"><input required type="datetime-local" value={rule1} onChange={e=>setRule1(e.target.value)}/></Field><Field label="30% refund until"><input required type="datetime-local" value={rule2} onChange={e=>setRule2(e.target.value)}/></Field></div><div className="policy-preview"><span>✳</span><p><b>Your rules, at a glance</b><br/>Full refund before the first deadline · 30% before the second · attend and receive 100% back.</p></div><label className="check-row"><input type="checkbox" checked={agree} onChange={e=>setAgree(e.target.checked)}/><span>I understand event terms lock when the first seat is registered.</span></label></section><section className="form-card"><div className="form-section-head"><span>03</span><div><h2>Who gets the invite?</h2><p>Choose how people can find you.</p></div></div><div className="visibility-choice"><button type="button" className={!privateEvent?"choice selected":"choice"} onClick={()=>setPrivateEvent(false)}><b>◉ Public</b><span>Show up in event discovery.</span></button><button type="button" className={privateEvent?"choice selected":"choice"} onClick={()=>setPrivateEvent(true)}><b>⌑ Private</b><span>Invite-only with an access code.</span></button></div>{privateEvent&&<Field label="Access code" hint="At least 8 characters. Never shown publicly."><input minLength={8} required value={code} onChange={e=>setCode(e.target.value)} placeholder="Create a private access code"/></Field>}</section></div><aside className="form-aside"><div className="sticky-card"><span className="aside-icon">✳</span><Eyebrow>BEFORE YOU PUBLISH</Eyebrow><h2>A seat is<br/><em>a promise.</em></h2><p>Your rules and deposit become part of each registration. They're locked after the first guest joins.</p><ul><li><span>✓</span> Clear refund deadlines</li><li><span>✓</span> Devnet SOL only</li><li><span>✓</span> Every change needs your wallet</li></ul><button className="button button-dark button-wide" disabled={busy||!agree}>{busy?"Creating draft…":"Create event draft"}<span>↗</span></button>{msg&&<div className="inline-message" role="status">{msg}</div>}<small className="aside-foot">No event is live until its on-chain transaction is confirmed.</small></div></aside></form></>}
function Field({label,hint,children}:{label:string;hint?:string;children:React.ReactNode}){const id=useMemo(()=>`f-${Math.random().toString(36).slice(2)}`,[]);return <div className="field"><label htmlFor={id}>{label}</label>{React.cloneElement(children as React.ReactElement<any>,{id})}{hint&&<small>{hint}</small>}</div>}

function ParticipantHome({go}:{go:(s:string)=>void}){const [tab,setTab]=useState("registrations");const [refresh,setRefresh]=useState(0);useEffect(()=>{const timer=window.setInterval(()=>setRefresh(x=>x+1),5000);return()=>window.clearInterval(timer)},[]);void refresh;return <DetailLoader load={()=>Promise.all([api.registrations(),api.waitlist(),api.disputes(),api.request<{items:TxIntent[]}>('/v1/me/attendance-intents')])} render={([regs,wait,disputes,intents])=><><PageIntro eyebrow="YOUR PLANS, ALL IN ONE PLACE" title={<>A seat with<br/><em>your name on it.</em></>} description="Your upcoming plans, check-ins, waitlist offers, and event history." action={<button className="button button-outline" onClick={()=>go("/events")}>Explore events ↗</button>}/><div className="dashboard-stats participant-stats"><Stat label="YOUR SEATS" value={String(regs.items.filter(x=>x.status==="reserved").length).padStart(2,"0")} icon="◉"/><Stat label="WAITLIST OFFERS" value={String(wait.items.filter(x=>x.status==="offered").length).padStart(2,"0")} icon="↗"/><Stat label="OPEN DISPUTES" value={String(disputes.items.filter(x=>x.status==="open").length).padStart(2,"0")} icon="⚑"/></div>{intents.items.length>0&&<section className="policy-card"><Eyebrow>ATTENDANCE APPROVAL REQUIRED</Eyebrow><h2>A scanner is waiting for your signature.</h2>{intents.items.map(i=><div className="organizer-row" key={i.intentId}><div className="row-color mint-color"><span>⌗</span></div><div className="row-main"><b>Check-in co-sign request</b><span>Expires {date(i.expiresAt)} · Devnet</span></div><button className="button button-dark" onClick={()=>void doAction(Promise.resolve(i),()=>{},setActionMessage)}>Review in Phantom</button></div>)}</section>}<div className="tabs" role="tablist">{([["registrations","My registrations"],["waitlist","Waitlist"],["disputes","Disputes"]] as const).map(([v,l])=><button role="tab" aria-selected={tab===v} className={tab===v?"active":""} onClick={()=>setTab(v)} key={v}>{l}<span>{v==="registrations"?regs.items.length:v==="waitlist"?wait.items.length:disputes.items.length}</span></button>)}</div>{tab==="registrations"?<RegistrationList items={regs.items} go={go}/>:tab==="waitlist"?<WaitlistList items={wait.items} go={go}/>:<DisputeList items={disputes.items} go={go}/> }</>}/>}
function RegistrationList({items,go}:{items:RegistrationView[];go:(s:string)=>void}){return <DetailLoader load={()=>Promise.all(items.map(async r=>({r,event:await api.event(r.eventId)})))} render={rows=>rows.length?<div className="organizer-list">{rows.map(({r,event:e})=><div className="organizer-row" key={r.id}><div className="row-color mint-color"><span>+</span></div><div className="row-main"><b>{e.title}</b><span>{e.location} | {date(e.policy.eventStartsAt)}</span></div><div className="row-seats"><b>{lamportsToSol(r.policySnapshot.depositLamports)}</b><span>Devnet SOL deposit</span></div><span className={`row-status ${r.status==="attended"?"attended":""}`}><i/> {r.status.replace("_"," ")}</span><Link className="row-arrow" to={`/registrations/${r.id}`} go={go}>&gt;</Link></div>)}</div>:<Empty icon="o" title="Your next good plan is out there" detail="Browse upcoming gatherings and save your first seat." action={<Link to="/events" go={go} className="text-button">Explore events</Link>}/>}/> }
function WaitlistList({items,go}:{items:WaitlistView[];go:(s:string)=>void}){return <DetailLoader load={()=>Promise.all(items.map(async w=>({w,event:await api.event(w.eventId)})))} render={rows=>rows.length?<div className="organizer-list">{rows.map(({w,event:e})=>{const seconds=w.offerExpiresAt?Math.max(0,w.offerExpiresAt-Math.floor(Date.now()/1000)):0;return <div className="organizer-row" key={w.id}><div className="row-color yellow-color"><span>&gt;</span></div><div className="row-main"><b>{e.title}</b><span>{w.status==="offered"?`Seat held for ${Math.floor(seconds/60)}m ${seconds%60}s; server expiry is final`:`Queue position ${w.position+1}`}</span></div><div className="row-seats"><b>{w.status}</b><span>{w.status==="offered"?"offer active":"free waitlist"}</span></div>{w.status==="offered"&&w.offerId?<Link className="button button-dark mini-button" to={`/offers/${w.offerId}`} go={go}>Review offer</Link>:<span className="row-arrow">&gt;</span>}</div>})}</div>:<Empty icon="&gt;" title="Room for one more?" detail="Join a free waitlist when an event fills up. If a seat opens, you will get a timed offer." action={<Link to="/events" go={go} className="text-button">Find a gathering</Link>}/>}/> }
function DisputeList({items,go}:{items:DisputeView[];go:(s:string)=>void}){return items.length?<div className="organizer-list">{items.map(d=><div className="organizer-row" key={d.id}><div className="row-color coral-color"><span>⚑</span></div><div className="row-main"><b>Attendance review</b><span>{d.status} · deadline {date(d.deadline)}</span></div><div className="row-seats"><b>{d.outcome??"In review"}</b><span>escrow remains locked</span></div><Link to={`/registrations/${d.registrationId}`} go={go} className="row-arrow">↗</Link></div>)}</div>:<Empty icon="⚑" title="All clear" detail="Any attendance disputes will appear here. Evidence stays private to the people involved."/>}

function Offer({id,go}:{id:string;go:(s:string)=>void}){return <DetailLoader load={async()=>{const page=await api.waitlist();const item=page.items.find(x=>x.offerId===id);return item?{item,event:await api.event(item.eventId)}:null}} render={data=>{if(!data)return <Empty icon="↗" title="This offer has expired" detail="Seat offers are time-limited. You can rejoin the free waitlist from the event page." action={<Link to="/events" go={go} className="button button-dark">Find events ↗</Link>}/>;const {item:w,event:e}=data;const expired=isOfferExpired(w.offerExpiresAt,Math.floor(Date.now()/1000));return <div className="offer-wrap"><div className="offer-stamp">A GOOD THING<br/>IS COMING YOUR WAY</div><Eyebrow>SEAT OFFER · POSITION {w.position+1}</Eyebrow><h1>Your wait is<br/><em>over.</em></h1><p className="offer-lead">A seat just opened up for <b>{e.title}</b>. It's being held just for you.</p><div className="offer-ticket"><div><small>YOUR SEAT</small><b>{e.title}</b><span>{e.location} · {date(e.policy.eventStartsAt)}</span></div><div className="ticket-deposit"><small>REFUNDABLE DEPOSIT</small><b>{lamportsToSol(e.policy.depositLamports)}</b></div></div><div className={`offer-countdown ${expired?"expired":""}`}><span>◷</span><div><b>{expired?"This offer has expired":"Your seat is held for a limited time"}</b><p>Server expiry: {w.offerExpiresAt?date(w.offerExpiresAt):"unknown"}. The countdown is only a guide—the server is authoritative.</p></div></div><button className="button button-dark button-wide" disabled={expired} onClick={()=>void doAction(api.action(`/v1/offers/${id}/accept`),()=>{},setActionMessage)}>Accept seat with Phantom <span>↗</span></button><button className="text-button centered-text" onClick={()=>void doAction(api.request(`/v1/events/${w.eventId}/waitlist`,{method:"DELETE"}),()=>{},setActionMessage)}>Leave waitlist</button><p className="inline-message" role="status">Offers expire on the server; an expired offer cannot be revived.</p></div>}}/>}
function setActionMessage(message:string){window.dispatchEvent(new CustomEvent("seatback-message",{detail:message}))}
function Scan({id,go}:{id:string;go:(s:string)=>void}){const [token,setToken]=useState("");const [status,setStatus]=useState("");const [camera,setCamera]=useState(false);const [video,setVideo]=useState<HTMLVideoElement|null>(null);const [stream,setStream]=useState<MediaStream|null>(null);useEffect(()=>{let active=true;let media:MediaStream|undefined;if(camera){navigator.mediaDevices?.getUserMedia({video:{facingMode:"environment"}}).then(s=>{media=s;if(active)setStream(s)}).catch(e=>setStatus(`Camera unavailable: ${errorText(e)}. Enter the token manually instead.`))}else{setStream(null)}return()=>{active=false;media?.getTracks().forEach(t=>t.stop())}},[camera]);useEffect(()=>{if(video&&stream)video.srcObject=stream},[video,stream]);useEffect(()=>{if(!camera||!video)return;const Detector=(window as Window&{BarcodeDetector?:new(o:{formats:string[]})=>{detect(v:HTMLVideoElement):Promise<Array<{rawValue:string}>>}}).BarcodeDetector;if(!Detector){setStatus("Automatic QR scanning is not supported by this browser. Enter the token manually instead.");return}const detector=new Detector({formats:["qr_code"]});let active=true;let frame=0;const scan=()=>{if(!active)return;void detector.detect(video).then(codes=>{const found=codes[0]?.rawValue;if(found){setToken(found);setStatus("QR token detected. Review the token and select Verify to continue.");return}frame=requestAnimationFrame(scan)}).catch(()=>{setStatus("Couldn’t read that QR. Try again or enter the token manually.");frame=requestAnimationFrame(scan)})};frame=requestAnimationFrame(scan);return()=>{active=false;cancelAnimationFrame(frame)}},[camera,video]);const verify=async(e:React.FormEvent)=>{e.preventDefault();if(!token.trim())return;try{await doAction(api.action(`/v1/events/${id}/attendance/verify`,{token:token.trim()}),()=>{},setStatus)}catch(e){setStatus(errorText(e))}};return <><div className="crumb"><button onClick={()=>go(`/organizer/events/${id}`)}>← Event overview</button></div><PageIntro eyebrow="DOOR DUTY" title={<>Check in.<br/><em>Say hello.</em></>} description="Scan a participant’s short-lived attendance token. Their wallet co-signature is required before check-in counts."/><div className="scan-layout"><div className="scan-box"><div className="scan-header"><span className="scan-icon">⌗</span><div><b>Attendance scanner</b><span>Authorized scanner · Devnet</span></div><span className="scan-lock">⌑ private</span></div><div className="camera-view">{camera&&stream?<video ref={setVideo} autoPlay muted playsInline/>:<><span className="camera-symbol">▣</span><b>Camera view</b><span>Keep the QR inside the frame</span></>}<div className="scan-corners"><i/><i/><i/><i/></div><span className="camera-caption">TOKEN EXPIRES AFTER 60 SECONDS</span></div><button className="button button-outline button-wide" onClick={()=>setCamera(!camera)}>{camera?"Turn camera off":"⌕ Start camera"}</button><div className="scan-divider"><span>OR ENTER TOKEN MANUALLY</span></div><form className="manual-token" onSubmit={verify}><label htmlFor="attendance-token">One-time check-in token</label><div><input id="attendance-token" value={token} onChange={e=>setToken(e.target.value)} placeholder="Paste participant token"/><button className="button button-dark">Verify ↗</button></div></form>{status&&<p className="inline-message" role="status">{status}</p>}</div><div className="scan-side"><span>01</span><h3>Scan their<br/><em>SeatBack QR.</em></h3><p>Tokens are private, scoped to one seat, and expire fast. Never accept screenshots of a wallet address.</p><span>02</span><h3>They approve<br/><em>on their phone.</em></h3><p>The participant signs the attendance intent in Phantom. Check-in is only complete once the chain confirms it.</p><p className="scan-warning">⏱ A successful scan alone is not a confirmed check-in.</p></div></div></>}


function RegistrationDetail({id,go}:{id:string;go:(s:string)=>void}){return <DetailLoader load={async()=>{const regs=await api.registrations();const r=regs.items.find(x=>x.id===id);if(!r)throw new Error("Registration not found");const event=await api.event(r.eventId);return {r,event}}} render={({r,event})=><RegistrationDetailView id={id} go={go} r={r} event={event}/>}/>;}
function RegistrationDetailView({id,go,r,event}:{id:string;go:(s:string)=>void;r:RegistrationView;event:EventView}){const [message,setMessage]=useState("");const [evidence,setEvidence]=useState("");const [qr,setQr]=useState<{token:string;expiresAt:number;image:string}|null>(null);const [qrBusy,setQrBusy]=useState(false);useEffect(()=>{if(!qr)return;const timer=window.setTimeout(()=>setQr(null),Math.max(0,qr.expiresAt*1000-Date.now()));return()=>window.clearTimeout(timer)},[qr]);const split=cancellationSplit(r.policySnapshot.depositLamports,Math.floor(Date.now()/1000),r.policySnapshot.rule1Deadline,r.policySnapshot.rule2Deadline);const participant=split.participant;const organizer=split.organizer;const submit=(path:string,body:unknown={})=>doAction(api.action(path,body),()=>{},setMessage);const requestQr=async()=>{setQrBusy(true);setMessage("");try{const data=await api.request<{token:string;expiresAt:number}>(`/v1/registrations/${r.id}/qr`,{method:"POST",body:"{}"});const image=await QRCode.toDataURL(data.token,{width:220,margin:1,errorCorrectionLevel:"M"});setQr({...data,image})}catch(e){setMessage(errorText(e))}finally{setQrBusy(false)}};return <><div className="crumb"><button onClick={()=>go("/me")}>← My seats</button></div><PageIntro eyebrow="YOUR SEAT" title={<>A plan worth<br/><em>keeping.</em></>} description={event.title+" · "+date(event.policy.eventStartsAt)}/><div className="registration-layout"><section className="reg-main"><div className="reg-status"><span className="status-icon">{r.status==="attended"?"✓":"◷"}</span><div><Eyebrow>REGISTRATION STATUS</Eyebrow><h2>{r.status.replace("_"," ")}</h2><span>{short(r.id)} · {r.transactionSignature?short(r.transactionSignature):"Demo record"}</span></div></div>{r.status==="reserved"&&<div className="qr-card"><div><Eyebrow>AT THE DOOR</Eyebrow><h2>Your check-in QR</h2><p>Request a short-lived token when you arrive. The scanner must be authorized, and you’ll approve the check-in on your phone.</p></div><button className="button button-dark" disabled={qrBusy} onClick={()=>void requestQr()}>{qrBusy?"Preparing…":"Generate check-in QR ↗"}</button>{qr&&<div className="qr-result"><img src={qr.image} alt="Short-lived event attendance QR code"/><span>Expires {date(qr.expiresAt)} · {date(qr.expiresAt,"UTC")} UTC</span><button className="text-button" onClick={()=>void navigator.clipboard.writeText(qr.token).then(()=>setMessage("The short-lived check-in token was copied."))}>Copy one-time token</button><small>Keep this private. The token expires automatically and can only be used once.</small></div>}</div>}<section className="policy-card"><Eyebrow>YOUR LOCKED-IN RULES</Eyebrow><h2>Terms saved at registration.</h2><PolicyTimeline policy={r.policySnapshot}/><div className="allocation-summary"><div><small>PARTICIPANT PAID</small><b>{lamportsToSol(r.participantRefundLamports)}</b></div><div><small>ORGANIZER ALLOCATION</small><b>{lamportsToSol(r.organizerAllocationLamports)}</b></div></div><p className="fine-print">Organizer allocation is an entitlement in escrow—not money already withdrawn.</p></section><section className="policy-card dispute-card"><Eyebrow>IF CHECK-IN DIDN’T GO TO PLAN</Eyebrow><h2>Dispute window</h2><p>File an attendance dispute before <b>{date(r.disputeDeadline)}</b> ({date(r.disputeDeadline,"UTC")} UTC). Evidence is private. An unresolved dispute keeps funds locked.</p><form onSubmit={e=>{e.preventDefault();submit(`/v1/registrations/${r.id}/disputes`,{evidenceText:evidence})}}><label htmlFor="evidence">What happened? (private, up to 4,000 characters)</label><textarea id="evidence" maxLength={4000} rows={3} value={evidence} onChange={e=>setEvidence(e.target.value)} placeholder="Describe the check-in issue…"/><button className="button button-outline" disabled={!evidence.trim()}>File dispute</button></form></section></section><aside className="reg-actions"><section className="booking-card"><Eyebrow>DEPOSIT SNAPSHOT</Eyebrow><div className="big-deposit">{lamportsToSol(r.policySnapshot.depositLamports)}</div><span className="devnet-label">◎ DEVNET SOL</span><div className="divider"/><div className="allocation-row"><span>Current refund</span><b>{lamportsToSol(r.participantRefundLamports)}</b></div><div className="allocation-row"><span>Potential early cancel</span><b>{lamportsToSol(participant)}</b></div><small className="fine-print">If cancelled now, {lamportsToSol(organizer)} is allocated to the organizer.</small><button className="button button-outline button-wide" disabled={r.status!=="reserved"} onClick={()=>submit(`/v1/registrations/${r.id}/cancel`)}>Cancel registration</button><button className="button button-text button-wide" onClick={()=>submit(`/v1/registrations/${r.id}/claim-refund`)}>Claim event-cancellation refund ↗</button><div className="booking-lock">Rent and network fees are separate</div></section></aside></div>{message&&<p className="inline-message" role="status">{message}</p>}</>}
function Arbiter({go}:{go:(s:string)=>void}){const [selected,setSelected]=useState<DisputeView|null>(null);const [message,setMessage]=useState("");return <DetailLoader load={()=>api.disputes(true)} render={d=><><PageIntro eyebrow="INDEPENDENT REVIEW" title={<>Help settle<br/><em>the hard parts.</em></>} description="Review disputes assigned to your arbiter wallet. Your decision requires a Phantom signature on Devnet."/><div className="arbiter-layout"><div className="dispute-queue"><Eyebrow>OPEN CASES · {d.items.filter(x=>x.status!=="resolved").length}</Eyebrow>{d.items.map(x=><button key={x.id} className={`dispute-item ${selected?.id===x.id?"selected":""}`} onClick={()=>setSelected(x)}><span className="case-id">CASE {x.id.slice(-5).toUpperCase()}</span><b>{short(x.participant)}</b><span>{x.status} <i>·</i> due {date(x.deadline)}</span></button>)}</div>{selected?<section className="case-detail"><Eyebrow>PRIVATE EVIDENCE</Eyebrow><h2>Case review</h2><p className="case-event">Event {short(selected.eventId)} · Registration {short(selected.registrationId)}</p><div className="evidence-box"><small>PARTICIPANT STATEMENT</small><p>{selected.evidenceText}</p></div><div className="case-warning">Unresolved disputes keep funds locked. A decision is final on-chain. Review only evidence you’re authorized to see.</div><div className="modal-actions"><button className="button button-outline" onClick={()=>setMessage("The dispute will remain open and funds locked.")}>Leave unresolved</button><button className="button button-outline" onClick={()=>void doAction(api.action(`/v1/disputes/${selected.id}/resolve`,{outcome:"participant"}),()=>{},setMessage)}>Refund participant</button><button className="button button-dark" onClick={()=>void doAction(api.action(`/v1/disputes/${selected.id}/resolve`,{outcome:"organizer"}),()=>{},setMessage)}>Award organizer</button></div>{message&&<p className="inline-message" role="status">{message}</p>}</section>:<Empty icon="⚑" title="Select a case" detail="Review assigned evidence and the deadline before making a decision."/>}</div></>}/>}
function NotFound({go}:{go:(s:string)=>void}){return <Empty icon="↗" title="This page wandered off" detail="The page you’re looking for isn’t here." action={<Link to="/events" go={go} className="button button-dark">Explore events ↗</Link>}/>}
function AuthRequired({connect,login,wallet}:{connect:()=>Promise<void>;login:()=>Promise<void>;wallet:string|null}){return <div className="auth-required"><span className="status-icon">⌑</span><Eyebrow>WALLET SESSION REQUIRED</Eyebrow><h1>Your wallet,<br/><em>your SeatBack.</em></h1><p>This page contains account-specific information. Connect Phantom, then sign a domain-bound message to continue. Connecting alone does not sign you in.</p>{wallet?<button className="button button-dark" onClick={()=>void login()}>Sign in with Phantom ↗</button>:<button className="button button-dark" onClick={()=>void connect()}>Connect Phantom ↗</button>}</div>}
function OrganizerAccess({id,go}:{id:string;go:(s:string)=>void}){return <DetailLoader load={()=>Promise.all([api.event(id),api.capabilities(id)])} render={([event,c])=>c.canManage?<OrganizerDynamic event={event} go={go}/>:<Empty icon="⌑" title="Organizer access required" detail="Capabilities for this wallet do not include event management."/>}/>}
function OrganizerDynamic({event,go}:{event:EventView;go:(s:string)=>void}){const [tab,setTab]=useState("overview");const [message,setMessage]=useState("");const [scannerWallet,setScannerWallet]=useState("");return <><div className="crumb"><button onClick={()=>go("/organizer/events")}>← Your events</button><span>/</span><span>{event.title}</span></div><PageIntro eyebrow="YOUR GATHERING" title={<>{event.title}<span className="title-badge">{event.status}</span></>} description={`${event.location} · ${date(event.policy.eventStartsAt)} · ${date(event.policy.eventStartsAt,"UTC")} UTC`} action={<button className="button button-outline" onClick={()=>go(`/scan/${event.id}`)}>⌗ Open scanner</button>}/><div className="tabs">{([["overview","Overview"],["participants","Participants"],["scanners","Scanners & roles"]] as const).map(([v,l])=><button className={tab===v?"active":""} onClick={()=>setTab(v)} key={v}>{l}</button>)}</div>{tab==="overview"?<><div className="dashboard-stats"><Stat label="SEATS FILLED" value={`${event.occupiedSeats}/${event.capacity}`} icon="◉"/><Stat label="HELD FOR OFFERS" value={String(event.heldOffers).padStart(2,"0")} icon="↗"/><Stat label="LIFETIME SIGNUPS" value={`${event.registrationsCreated}/${event.registrationLimit}`} icon="✳"/></div><section className="panel"><Eyebrow>THE PROMISE</Eyebrow><h2>Refund policy</h2><PolicyTimeline policy={event.policy}/><p>Event cancellation makes every remaining deposit individually claimable. Disputes keep escrow locked.</p><button className="button button-danger" onClick={()=>void doAction(api.action(`/v1/events/${event.id}/cancel`),()=>{},setMessage)}>Review event cancellation</button></section></>:tab==="participants"?<DetailLoader load={()=>api.participants(event.id)} render={p=>p.items.length?<div className="participants-table"><div className="table-head"><span>PARTICIPANT</span><span>STATUS</span><span>DEPOSIT</span><span>REFUND</span><span/></div>{p.items.map(r=><div className="table-row" key={r.id}><b>{short(r.wallet)}</b><span className="row-status"><i/> {r.status}</span><span>{lamportsToSol(r.policySnapshot.depositLamports)}</span><span>{lamportsToSol(r.participantRefundLamports)}</span><span><button className="text-button" onClick={()=>void doAction(api.action(`/v1/registrations/${r.id}/withdraw`),()=>{},setMessage)}>Review settlement in Phantom</button></span></div>)}</div>:<Empty icon="◉" title="No confirmed seats yet" detail="Participants appear after their registration transactions are confirmed."/>}/> :<section className="role-panel"><div className="role-symbol">⌗</div><div><Eyebrow>SCAN ACCESS</Eyebrow><h2>Scanner roles follow<br/><em>on-chain authority.</em></h2><p>Assign or remove a scanner. Changes require organizer approval in Phantom.</p></div><div className="role-action"><label htmlFor="scanner-wallet">Wallet address</label><input id="scanner-wallet" value={scannerWallet} onChange={e=>setScannerWallet(e.target.value)} placeholder="Scanner public key"/><button className="button button-dark" disabled={!scannerWallet.trim()} onClick={()=>void doAction(api.action(`/v1/events/${event.id}/scanners`,{wallet:scannerWallet.trim()}),()=>{},setMessage)}>Add scanner</button></div></section>}{message&&<p className="inline-message" role="status">{message}</p>}</>}
function ScannerAccess({id,go}:{id:string;go:(s:string)=>void}){return <DetailLoader load={()=>api.capabilities(id)} render={c=>c.canScan?<Scan id={id} go={go}/>:<Empty icon="⌑" title="Scanner access required" detail="The connected wallet is not authorized to scan attendance for this event."/>}/>}
function ArbiterAccess({go}:{go:(s:string)=>void}){return <DetailLoader load={async()=>{const disputes=await api.disputes(true);const caps=await Promise.all(disputes.items.map(d=>api.capabilities(d.eventId)));return caps.some(c=>c.canArbitrate)}} render={allowed=>allowed?<Arbiter go={go}/>:<Empty icon="⚑" title="No arbiter cases assigned" detail="The dispute queue is empty or this wallet has no arbiter capability for assigned cases."/>}/>}
const root=document.getElementById("root");if(!root)throw new Error("Missing root");
createRoot(root).render(<React.StrictMode><App/></React.StrictMode>);
